entry.summary:
-- Create database if missing CREATE DATABASE IF NOT EXISTS task_db; USE task_db;
-- Role table CREATE TABLE IF NOT EXISTS role ( id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255) );
-- Insert default roles INSERT IGNORE INTO role (name, description) VALUES ('admin', 'Full system access'), ('customer', 'Can browse and place orders'), ('staff', 'Can manage orders and products'), ('vendor', 'Supplier with limited access');
-- User table CREATE TABLE IF NOT EXISTS user ( id INT AUTO_INCREMENT PRIMARY KEY, role_id INT NOT NULL, firstName VARCHAR(100) NOT NULL, lastName VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(20), created_at TIMESTAMP D…
